INSERT [dbo].[Attractions] ([id], [name], [distance_km], [description], [map_embed_link], [latitude], [longitude], [address], [is_active], [category], [image_url], [created_at], [updated_at]) VALUES (11, N'Văn miếu Trấn Biên', CAST(5.00 AS Decimal(5, 2)), N'Văn miếu Trấn Biên được xây dựng năm 1715, là văn miếu đầu tiên ở Nam Bộ, thờ Khổng Tử và các bậc hiền triết. Đây là điểm tham quan văn hóa - lịch sử nổi bật nhất Biên Hòa với kiến trúc cổ kính uy nghiêm.', NULL, CAST(10.94780000 AS Decimal(10, 8)), CAST(106.85300000 AS Decimal(11, 8)), N'Phường Bửu Long, TP. Biên Hòa, Đồng Nai', 1, N'Lịch sử - Văn hóa', N'https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=1200&q=80', CAST(N'2026-04-20T20:55:55.890' AS DateTime), CAST(N'2026-04-20T20:55:55.890' AS DateTime))
INSERT [dbo].[Attractions] ([id], [name], [distance_km], [description], [map_embed_link], [latitude], [longitude], [address], [is_active], [category], [image_url], [created_at], [updated_at]) VALUES (12, N'Khu du lịch Bửu Long', CAST(6.00 AS Decimal(5, 2)), N'Khu du lịch sinh thái Bửu Long nổi tiếng với hồ Long Ẩn xanh biếc, núi đá vôi hùng vĩ và chùa Bửu Phong cổ kính. Là điểm đến lý tưởng cho du khách muốn tận hưởng thiên nhiên ngay trong thành phố.', NULL, CAST(10.95200000 AS Decimal(10, 8)), CAST(106.86000000 AS Decimal(11, 8)), N'Phường Bửu Long, TP. Biên Hòa, Đồng Nai', 1, N'Thiên nhiên', N'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=1200&q=80', CAST(N'2026-04-20T20:55:55.890' AS DateTime), CAST(N'2026-04-20T20:55:55.890' AS DateTime))
INSERT [dbo].[Attractions] ([id], [name], [distance_km], [description], [map_embed_link], [latitude], [longitude], [address], [is_active], [category], [image_url], [created_at], [updated_at]) VALUES (13, N'Chùa Đại Giác', CAST(3.50 AS Decimal(5, 2)), N'Chùa Đại Giác (còn gọi là chùa Phật lớn) được xây dựng từ thế kỷ XVIII, nằm bên bờ sông Đồng Nai. Là một trong những ngôi chùa cổ nhất Biên Hòa với kiến trúc pha trộn Á - Âu độc đáo.', NULL, CAST(10.95100000 AS Decimal(10, 8)), CAST(106.82250000 AS Decimal(11, 8)), N'Xã Hiệp Hòa, TP. Biên Hòa, Đồng Nai', 1, N'Tâm linh', N'https://images.unsplash.com/photo-1545569341-9eb8b30979d9?auto=format&fit=crop&w=1200&q=80', CAST(N'2026-04-20T20:55:55.890' AS DateTime), CAST(N'2026-04-20T20:55:55.890' AS DateTime))
INSERT [dbo].[Attractions] ([id], [name], [distance_km], [description], [map_embed_link], [latitude], [longitude], [address], [is_active], [category], [image_url], [created_at], [updated_at]) VALUES (14, N'Cù lao Phố', CAST(4.00 AS Decimal(5, 2)), N'Cù lao Phố là vùng đất lịch sử nằm giữa sông Đồng Nai, từng là thương cảng sầm uất nhất Nam Bộ thế kỷ XVII-XVIII. Hiện nay nơi đây còn lưu giữ nhiều di tích lịch sử, đình chùa cổ và làng nghề truyền thống.', NULL, CAST(10.95050000 AS Decimal(10, 8)), CAST(106.81800000 AS Decimal(11, 8)), N'Xã Hiệp Hòa, TP. Biên Hòa, Đồng Nai', 1, N'Lịch sử - Văn hóa', N'https://images.unsplash.com/photo-1583417319070-4a69db38a482?auto=format&fit=crop&w=1200&q=80', CAST(N'2026-04-20T20:55:55.890' AS DateTime), CAST(N'2026-04-20T20:55:55.890' AS DateTime))
INSERT [dbo].[Attractions] ([id], [name], [distance_km], [description], [map_embed_link], [latitude], [longitude], [address], [is_active], [category], [image_url], [created_at], [updated_at]) VALUES (15, N'Làng bưởi Tân Triều', CAST(8.00 AS Decimal(5, 2)), N'Làng bưởi Tân Triều nổi tiếng cả nước với giống bưởi da xanh và bưởi đường lá cam thơm ngon. Du khách có thể tham quan vườn bưởi, thưởng thức trái cây tươi và trải nghiệm đời sống miệt vườn Nam Bộ.', NULL, CAST(10.98000000 AS Decimal(10, 8)), CAST(106.84000000 AS Decimal(11, 8)), N'Xã Tân Bình, Huyện Vĩnh Cửu, Đồng Nai', 1, N'Ẩm thực - Trải nghiệm', N'https://res.cloudinary.com/dwkqcuanf/image/upload/v1778257010/HotelManagement/Attractions/15/ghcsxogvo3eq0pcevmr1.jpg', CAST(N'2026-04-20T20:55:55.890' AS DateTime), CAST(N'2026-05-08T16:16:53.870' AS DateTime))
INSERT [dbo].[Attractions] ([id], [name], [distance_km], [description], [map_embed_link], [latitude], [longitude], [address], [is_active], [category], [image_url], [created_at], [updated_at]) VALUES (16, N'Chợ Biên Hòa', NULL, N'Chợ Biên Hòa là ngôi chợ truyền thống lâu đời nhất thành phố, nơi hội tụ đủ loại đặc sản Đồng Nai từ bưởi Tân Triều, gốm Biên Hòa đến các món ăn dân dã. Là điểm đến không thể bỏ qua để trải nghiệm văn hóa ẩm thực địa phương.', NULL, CAST(10.94580000 AS Decimal(10, 8)), CAST(106.82690000 AS Decimal(11, 8)), N'Đường Nguyễn Văn Trị, P. Thanh Bình, TP. Biên Hòa', 1, N'Ẩm thực - Trải nghiệm', N'https://res.cloudinary.com/dwkqcuanf/image/upload/v1777049842/HotelManagement/Attractions/16/fzonjai8jgfksw151xyw.jpg', CAST(N'2026-04-20T20:55:55.890' AS DateTime), CAST(N'2026-04-24T16:57:24.263' AS DateTime))
INSERT [dbo].[Attractions] ([id], [name], [distance_km], [description], [map_embed_link], [latitude], [longitude], [address], [is_active], [category], [image_url], [created_at], [updated_at]) VALUES (17, N'Vườn quốc gia Cát Tiên', CAST(150.00 AS Decimal(5, 2)), N'Vườn quốc gia Cát Tiên là khu bảo tồn thiên nhiên UNESCO, nơi lưu giữ hệ sinh thái rừng nhiệt đới nguyên sinh phong phú với nhiều loài động thực vật quý hiếm. Cách Biên Hòa khoảng 150km, lý tưởng cho chuyến đi 2 ngày 1 đêm.', NULL, CAST(11.42500000 AS Decimal(10, 8)), CAST(107.42600000 AS Decimal(11, 8)), N'Huyện Tân Phú, Đồng Nai', 1, N'Thiên nhiên', N'https://images.unsplash.com/photo-1448375240586-882707db888b?auto=format&fit=crop&w=1200&q=80', CAST(N'2026-04-20T20:55:55.890' AS DateTime), CAST(N'2026-04-20T20:55:55.890' AS DateTime))
INSERT [dbo].[Attractions] ([id], [name], [distance_km], [description], [map_embed_link], [latitude], [longitude], [address], [is_active], [category], [image_url], [created_at], [updated_at]) VALUES (18, N'Thác Giang Điền', CAST(25.00 AS Decimal(5, 2)), N'Khu du lịch Thác Giang Điền là điểm đến nghỉ dưỡng cuối tuần lý tưởng với thác nước mát lạnh, hồ bơi, khu cắm trại và nhiều trò chơi ngoài trời. Thích hợp cho gia đình và nhóm bạn.', NULL, CAST(10.91000000 AS Decimal(10, 8)), CAST(106.97000000 AS Decimal(11, 8)), N'Xã Giang Điền, Huyện Trảng Bom, Đồng Nai', 1, N'Thiên nhiên', N'https://res.cloudinary.com/dwkqcuanf/image/upload/v1777049686/HotelManagement/Attractions/18/eyos21kaqshjixszfmjn.jpg', CAST(N'2026-04-20T20:55:55.890' AS DateTime), CAST(N'2026-04-24T16:54:48.210' AS DateTime))
